#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    int round;
    std::cin >> round;
    std::vector<int> firstperson(round);
    std::vector<int> secondperson(round);
    for (int i = 0; i < round; ++i) {
        std::cin >> firstperson[i];
    }
    for (int i = 0; i < round; ++i) {
        std::cin >> secondperson[i];
    }

    int total_win = 0;
    std::vector<int> sp_extended = secondperson;
    sp_extended.push_back(secondperson[0]);

    for (int i = 0; i < round; ++i) {
        total_win += std::min(firstperson[i], sp_extended[i + 1]);
    }

    // Modify secondperson as per the original code
    int last_element = secondperson.back();
    secondperson.pop_back();
    secondperson.insert(secondperson.begin(), last_element);

    for (int i = 0; i < round; ++i) {
        if (firstperson[i] > 0) {
            int diff = std::min(firstperson[i], secondperson[i]);
            firstperson[i] -= diff;
            secondperson[i] -= diff;
            if (firstperson[i] > 0) {
                int diff2 = std::min(firstperson[i], secondperson[i + 1]);
                firstperson[i] -= diff2;
                secondperson[i + 1] -= diff2;
            }
        }
    }

    std::cout << std::accumulate(firstperson.begin(), firstperson.end(), 0) << " " << total_win << std::endl;

    return 0;
}
